CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, data TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY CHECK (id = 1), data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth (id INTEGER PRIMARY KEY CHECK (id = 1), salt TEXT NOT NULL, hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS images (key TEXT PRIMARY KEY, type TEXT NOT NULL, data BLOB NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (ip TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_ip ON attempts (ip, at);
CREATE TABLE IF NOT EXISTS orders (id INTEGER PRIMARY KEY AUTOINCREMENT, created INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pendiente', name TEXT NOT NULL, phone TEXT NOT NULL, mode TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', items TEXT NOT NULL, total INTEGER NOT NULL, done_at INTEGER);
CREATE INDEX IF NOT EXISTS orders_status ON orders (status, created);
ALTER TABLE orders ADD COLUMN delivery INTEGER;
CREATE TABLE IF NOT EXISTS visits (id INTEGER PRIMARY KEY AUTOINCREMENT, at INTEGER NOT NULL, page TEXT NOT NULL, mine INTEGER NOT NULL DEFAULT 0, city TEXT, region TEXT, country TEXT, device TEXT, browser TEXT);
CREATE INDEX IF NOT EXISTS visits_at ON visits (at);
ALTER TABLE orders ADD COLUMN confirmed_at INTEGER;
